// Accept either { sources: [{name, kind, text}] } or { text: '...' }.
// Truncate any single source to ~12k chars and the total to ~30k chars to
// keep the prompt within Sonnet's budget. The analyzer is more useful with
// more sources than longer ones — we cap aggressively.
const body = $input.first().json.body ?? $input.first().json;
let sources = Array.isArray(body.sources) ? body.sources : null;
if (!sources && body.text) sources = [{ name: 'inline', kind: 'txt', text: body.text }];
if (!sources || sources.length === 0) throw new Error('no_sources');
sources = sources.map((s, i) => ({
  index: i + 1,
  name: (s.name || 'source ' + (i + 1)).toString().slice(0, 80),
  kind: s.kind || 'txt',
  text: (s.text || '').toString().slice(0, 12000),
}));
let total = 0;
const trimmed = [];
for (const s of sources) {
  if (total + s.text.length > 30000) {
    const room = Math.max(0, 30000 - total);
    if (room > 1500) trimmed.push({ ...s, text: s.text.slice(0, room) });
    break;
  }
  trimmed.push(s);
  total += s.text.length;
}
return [{ json: { sources: trimmed, total_chars: total, hint_category: body.hint_category ?? null, hint_language: body.hint_language ?? null } }];

