// Parse Claude's JSON. Add safety nets: if the model returned partial JSON
// or wrapped it in markdown fences, recover gracefully.
let text = $input.first().json.message ?? $input.first().json.text ?? $input.first().json.content ?? '';
text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let v;
try { v = JSON.parse(text); } catch (_e) {
  return [{ json: { error: 'parse_failed', raw: text.slice(0, 2000) } }];
}
// Compute overall_completeness if missing
if (!v.overall_completeness && v.confidence) {
  const vals = Object.values(v.confidence);
  v.overall_completeness = vals.length ? vals.reduce((s, x) => s + x, 0) / vals.length : 0;
}
// Compute gaps if missing
if (!Array.isArray(v.gaps) && v.confidence) {
  v.gaps = Object.entries(v.confidence).filter(([_, c]) => c < 0.6).map(([k]) => k);
}
// Inject analyzed metadata from input
v.word_count_analyzed = $('parse').first().json.total_chars / 5 | 0;  // approx words from chars
return [{ json: v }];
